static int addattr(struct nlmsghdr*n,size_t max,int type,const void*data,size_t len){size_t total=RTA_LENGTH(len),next=NLMSG_ALIGN(n->nlmsg_len)+RTA_ALIGN(total);if(next>max)return-1;struct rtattr*r=(struct rtattr*)((char*)n+NLMSG_ALIGN(n->nlmsg_len));r->rta_type=type;r->rta_len=(unsigned short)total;memcpy(RTA_DATA(r),data,len);n->nlmsg_len=(unsigned)next;return 0;}
