static int sealed_process(long pid,unsigned long long expected_start,const char*worker){char path[64],buffer[8192];snprintf(path,sizeof(path),"/proc/%ld/stat",pid);int fd=open(path,O_RDONLY|O_CLOEXEC);if(fd<0)return 0;ssize_t size=read(fd,buffer,sizeof(buffer)-1);close(fd);if(size<=0)return 0;buffer[size]='\0';char*cursor=strrchr(buffer,')');if(!cursor)return 0;cursor+=2;char*save=NULL,*token=strtok_r(cursor," ",&save);int field=3;unsigned long long start=0;while(token){if(field++==22){start=strtoull(token,NULL,10);break;}token=strtok_r(NULL," ",&save);}if(start!=expected_start)return 0;snprintf(path,sizeof(path),"/proc/%ld/cgroup",pid);fd=open(path,O_RDONLY|O_CLOEXEC);if(fd<0)return 0;size=read(fd,buffer,sizeof(buffer)-1);close(fd);if(size<=0)return 0;buffer[size]='\0';return strstr(buffer,worker)!=NULL;}
static int dump(int type,int family,unsigned seq,char*b,size_t cap,ssize_t*size){int fd=socket(AF_NETLINK,SOCK_RAW|SOCK_CLOEXEC,NETLINK_ROUTE);if(fd<0)return-1;struct{struct nlmsghdr n;struct rtgenmsg g;}q={{NLMSG_LENGTH(sizeof(struct rtgenmsg)),type,NLM_F_REQUEST|NLM_F_DUMP,seq,0},{(unsigned char)family}};struct sockaddr_nl nl={.nl_family=AF_NETLINK};if(sendto(fd,&q,q.n.nlmsg_len,0,(struct sockaddr*)&nl,sizeof(nl))<0){close(fd);return-1;}*size=0;int done=0;while(!done){if((size_t)*size==cap){close(fd);return-1;}struct sockaddr_nl from={0};struct iovec iov={b+*size,cap-(size_t)*size};struct msghdr msg={.msg_name=&from,.msg_namelen=sizeof(from),.msg_iov=&iov,.msg_iovlen=1};ssize_t got=recvmsg(fd,&msg,0);if(got<=0||(msg.msg_flags&MSG_TRUNC)||from.nl_pid!=0){close(fd);return-1;}ssize_t remaining=got;for(struct nlmsghdr*n=(void*)(b+*size);NLMSG_OK(n,(unsigned)remaining);n=NLMSG_NEXT(n,remaining)){if(n->nlmsg_seq!=seq||n->nlmsg_pid!=0){close(fd);return-1;}if(n->nlmsg_type==NLMSG_ERROR){struct nlmsgerr*e=NLMSG_DATA(n);if(n->nlmsg_len<NLMSG_LENGTH(sizeof(*e))||e->error){close(fd);return-1;}}if(n->nlmsg_type==NLMSG_DONE)done=1;}if(remaining!=0){close(fd);return-1;}*size+=got;}close(fd);return done?0:-1;}
