static int addresses_ok(unsigned expected_if,struct in_addr worker){char b[65536];ssize_t size;if(dump(RTM_GETADDR,AF_UNSPEC,22,b,sizeof(b),&size))return 0;int matches=0;unsigned lo=if_nametoindex("lo");for(struct nlmsghdr*n=(void*)b;NLMSG_OK(n,(unsigned)size);n=NLMSG_NEXT(n,size)){if(n->nlmsg_type==NLMSG_DONE)break;if(n->nlmsg_type!=RTM_NEWADDR)return 0;struct ifaddrmsg*a=NLMSG_DATA(n);if(a->ifa_index!=expected_if&&a->ifa_index!=lo)return 0;if(a->ifa_family==AF_INET6&&a->ifa_index==expected_if)return 0;if(a->ifa_index!=expected_if||a->ifa_family!=AF_INET)continue;int len=IFA_PAYLOAD(n),exact=0;for(struct rtattr*r=IFA_RTA(a);RTA_OK(r,len);r=RTA_NEXT(r,len))if(r->rta_type==IFA_LOCAL||r->rta_type==IFA_ADDRESS){struct in_addr v;memcpy(&v,RTA_DATA(r),sizeof(v));if(v.s_addr!=worker.s_addr||a->ifa_prefixlen!=28)return 0;exact=1;}if(len||!exact)return 0;matches++;}return matches==1;}
static int routes_ok(unsigned expected_if,struct in_addr gateway,int canonical){char b[65536];ssize_t size;if(dump(RTM_GETROUTE,AF_INET,23,b,sizeof(b),&size))return 0;int defaults=0,match=0;unsigned lo=if_nametoindex("lo");for(struct nlmsghdr*n=(void*)b;NLMSG_OK(n,(unsigned)size);n=NLMSG_NEXT(n,size)){if(n->nlmsg_type==NLMSG_DONE)break;if(n->nlmsg_type!=RTM_NEWROUTE)return 0;struct rtmsg*r=NLMSG_DATA(n);if(r->rtm_family!=AF_INET)return 0;if(r->rtm_table!=RT_TABLE_MAIN&&r->rtm_table!=RT_TABLE_LOCAL)return 0;if(r->rtm_type!=RTN_UNICAST&&r->rtm_type!=RTN_LOCAL&&r->rtm_type!=RTN_BROADCAST)return 0;unsigned oif=0,metric=0;struct in_addr gw={0};int len=RTM_PAYLOAD(n);for(struct rtattr*a=RTM_RTA(r);RTA_OK(a,len);a=RTA_NEXT(a,len)){if(a->rta_type==RTA_MULTIPATH)return 0;if(a->rta_type==RTA_OIF)memcpy(&oif,RTA_DATA(a),sizeof(oif));else if(a->rta_type==RTA_GATEWAY)memcpy(&gw,RTA_DATA(a),sizeof(gw));else if(a->rta_type==RTA_PRIORITY)memcpy(&metric,RTA_DATA(a),sizeof(metric));}if(len||(oif&&oif!=expected_if&&oif!=lo))return 0;if(r->rtm_table==RT_TABLE_MAIN&&!r->rtm_dst_len){defaults++;if(oif==expected_if&&(!canonical||(gw.s_addr==gateway.s_addr&&metric==100)))match=1;}}return defaults==1&&match;}
static int network_ok(unsigned i,struct in_addr worker,struct in_addr gateway,int canonical){return rules_ok()&&addresses_ok(i,worker)&&routes_ok(i,gateway,canonical);}
static int replace_default(unsigned i,struct in_addr gateway){int fd=socket(AF_NETLINK,SOCK_RAW|SOCK_CLOEXEC,NETLINK_ROUTE);if(fd<0)return-1;struct{struct nlmsghdr n;struct rtmsg r;char attrs[128];}q={0};q.n.nlmsg_len=NLMSG_LENGTH(sizeof(q.r));q.n.nlmsg_type=RTM_NEWROUTE;q.n.nlmsg_seq=24;q.n.nlmsg_flags=NLM_F_REQUEST|NLM_F_ACK|NLM_F_CREATE|NLM_F_REPLACE;q.r.rtm_family=AF_INET;q.r.rtm_table=RT_TABLE_MAIN;q.r.rtm_protocol=RTPROT_STATIC;q.r.rtm_scope=RT_SCOPE_UNIVERSE;q.r.rtm_type=RTN_UNICAST;uint32_t metric=100;if(addattr(&q.n,sizeof(q),RTA_GATEWAY,&gateway,sizeof(gateway))||addattr(&q.n,sizeof(q),RTA_OIF,&i,sizeof(i))||addattr(&q.n,sizeof(q),RTA_PRIORITY,&metric,sizeof(metric))){close(fd);return-1;}struct sockaddr_nl nl={.nl_family=AF_NETLINK};if(sendto(fd,&q,q.n.nlmsg_len,0,(void*)&nl,sizeof(nl))<0){close(fd);return-1;}char reply[4096];ssize_t size=recv(fd,reply,sizeof(reply),0);struct nlmsghdr*n=(void*)reply;int ok=size>=(ssize_t)NLMSG_LENGTH(sizeof(struct nlmsgerr))&&n->nlmsg_type==NLMSG_ERROR&&n->nlmsg_seq==24&&((struct nlmsgerr*)NLMSG_DATA(n))->error==0;close(fd);return ok?0:-1;}
int main(int argc,char**argv){if(argc!=3||strcmp(argv[1],"--digest")||strlen(argv[2])!=71||strncmp(argv[2],"sha256:",7)||!capabilities())return 64;char request[4097];ssize_t count=read(0,request,sizeof(request)-1);if(count<=0||count>=4096)return 65;request[count]='\0';char*fields[14],*save=NULL,*part=strtok_r(request,";",&save);int n=0;while(part&&n<14){fields[n++]=part;part=strtok_r(NULL,";",&save);}if(n!=14||part)return 66;int mutate=!strcmp(fields[0],"REPLACE_WORKER_DEFAULT_ROUTE");if(!mutate&&strcmp(fields[0],"INSPECT_WORKER_NETWORK_STATE"))return 67;char*end=NULL;long pid=strtol(fields[2],&end,10);if(!end||*end||pid<=0)return 68;unsigned long long start=strtoull(fields[3],&end,10);if(!end||*end||!start||!hex64(fields[1])||!hex64(fields[6])||!sealed_process(pid,start,fields[1]))return 74;unsigned long long dev=strtoull(fields[4],&end,10);if(!end||*end||!dev)return 75;unsigned long long ino=strtoull(fields[5],&end,10);if(!end||*end||!ino)return 75;unsigned long generation=strtoul(fields[10],&end,10);if(!end||*end||!generation||!fields[11][0]||!fields[12][0]||!fields[13][0])return 75;char path[64];snprintf(path,sizeof(path),"/proc/%ld/ns/net",pid);int ns=open(path,O_RDONLY|O_CLOEXEC);struct stat st;if(ns<0||fstat(ns,&st)||st.st_dev!=(dev_t)dev||st.st_ino!=(ino_t)ino||setns(ns,CLONE_NEWNET)){if(ns>=0)close(ns);return 69;}close(ns);unsigned i=if_nametoindex(fields[9]);struct in_addr worker,gateway;if(!i||inet_pton(AF_INET,fields[7],&worker)!=1||inet_pton(AF_INET,fields[8],&gateway)!=1)return 70;if(mutate&&!network_ok(i,worker,gateway,0))return 76;if(mutate&&replace_default(i,gateway))return 71;if(!network_ok(i,worker,gateway,1))return 72;if(write(1,"ROUTE_CANONICAL",15)!=15)return 73;return 0;}
